        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        x = x.contiguous()
        weight = self.conv_transpose2d.weight.contiguous()

        N, IC, IH, IW = x.shape
        OC = self.out_channels
        kH, kW = self.kernel_size
        sH, sW = self.stride
        pH, pW = self.padding
        dH, dW = self.dilation

        OH = (IH - 1) * sH - 2 * pH + dH * (kH - 1) + 1
        OW = (IW - 1) * sW - 2 * pW + dW * (kW - 1) + 1

        output = torch.empty((N, OC, OH, OW), dtype=x.dtype, device=x.device)

        total = N * OC * OH * OW

        module = _get_ptx_module()

        block = (256, 1, 1)
        grid = (N * self.groups, 8, 1)

        module.launch(
            "conv_transpose2d_kernel",
            grid=grid,
            block=block,
            arguments=[x, weight, output, i32(total)],
            shared_memory=7680,
            stream=torch.cuda.current_stream(x.device),
        )

        return output

